    "zeroth",
    "first",
    "second",
    "third",
    "fourth",
    "fifth",
    "sixth",
    "seventh",
    "eighth",
    "ninth",
  ]);
  checkSelection([]);

  // Select some rows. This selection should be preserved throughout the test.

  adapter.selection.toggleSelect(0);
  adapter.selection.toggleSelect(4);
  adapter.selection.toggleSelect(8);
  checkSelection([0, 4, 8]);

